42	func parseRuntimeOptions() runtimeOptions {
43		var (
44			configPath             = flag.String("config", "config/config.yaml", "Path to the configuration file")
45			port                   = flag.Int("port", 50051, "Port to listen on for gRPC ExtProc")
46			apiPort                = flag.Int("api-port", 8080, "Port to listen on for the router apiserver")
47			apiBind                = flag.String("api-bind", "", "Bind address for the router apiserver (default from config: 127.0.0.1)")
48			managementAuthMode     = flag.String("management-auth-mode", "", "Management API auth mode: bearer or disabled")
49			managementRemoteExpose = flag.Bool("management-remote-exposure", false, "Allow remote exposure of the management API (requires bearer auth tokens in config)")
50			metricsPort            = flag.Int("metrics-port", 9190, "Port for Prometheus metrics")
51			enableAPI              = flag.Bool("enable-api", true, "Enable the router apiserver")
52			secure                 = flag.Bool("secure", false, "Enable secure gRPC server with TLS")
53			certPath               = flag.String("cert-path", "", "Path to TLS certificate directory (containing tls.crt and tls.key)")
54			kubeconfig             = flag.String("kubeconfig", "", "Path to kubeconfig file (optional, uses in-cluster config if not specified)")
55			namespace              = flag.String("namespace", "default", "Kubernetes namespace to watch for CRDs")
56			downloadOnly           = flag.Bool("download-only", false, "Download required models and exit (useful for CI/testing)")
57		)
58		flag.Parse()
59	
60		return runtimeOptions{
61			configPath:             *configPath,
62			certPath:               *certPath,
63			kubeconfig:             *kubeconfig,
64			namespace:              *namespace,
65			port:                   *port,
66			apiPort:                *apiPort,
67			apiBind:                *apiBind,
68			managementAuthMode:     *managementAuthMode,
69			managementRemoteExpose: boolFlagOverride(flag.CommandLine, "management-remote-exposure", *managementRemoteExpose),
70			metricsPort:            *metricsPort,
71			enableAPI:              *enableAPI,
72			secure:                 *secure,
73			downloadOnly:           *downloadOnly,
74		}
75	}
76	
77	// boolFlagOverride returns a pointer to value only when the named flag was
78	// explicitly supplied on the command line. Otherwise nil so config defaults
79	// are preserved (e.g. management_api.remote_exposure: true).
80	func boolFlagOverride(fs *flag.FlagSet, name string, value bool) *bool {
81		set := false
82		fs.Visit(func(f *flag.Flag) {
83			if f.Name == name {
84				set = true
85			}
86		})
87		if !set {
88			return nil
89		}
90		return &value
91	}
92	
93	func initializeRuntimeLogger() {
94		if _, err := logging.InitLoggerFromEnv(); err != nil {
95			fmt.Fprintf(os.Stderr, "failed to initialize logger: %v\n", err)
96		}
97	}
98	
99	func loadRuntimeConfigOrFatal(configPath string) *config.RouterConfig {
100		if _, err := os.Stat(configPath); os.IsNotExist(err) {
101			logging.ComponentFatalEvent("router", "runtime_config_missing", map[string]interface{}{
102				"config_path": configPath,
103			})
104		}
105	
106		cfg, err := config.Parse(configPath)
107		if err != nil {
108			logging.ComponentFatalEvent("router", "runtime_config_load_failed", map[string]interface{}{
109				"config_path": configPath,
110				"error":       err.Error(),
111			})
112		}
113		logging.ComponentDebugEvent("router", "runtime_config_loaded", map[string]interface{}{
114			"config_path":    configPath,
115			"config_source":  cfg.ConfigSource,
116			"decision_count": len(cfg.Decisions),
117		})
118		return cfg
119	}
120	
121	func newStartupWriter(cfg *config.RouterConfig, configPath string) startupstatus.StatusWriter {
122		writer := buildStartupWriter(cfg, configPath)
123		writeStartupState(writer, startupstatus.State{
124			Phase:   "starting",
125			Ready:   false,
126			Message: "Router process booting...",
127		}, "Failed to write initial startup status")
128		return writer
129	}
130	
131	func buildStartupWriter(cfg *config.RouterConfig, configPath string) startupstatus.StatusWriter {
132		if cfg.StartupStatus.StoreBackend == "redis" && cfg.StartupStatus.Redis != nil {
133			rw, err := startupstatus.NewRedisWriter(startupstatus.RedisWriterConfig{
134				Address:  cfg.StartupStatus.Redis.Address,
135				Password: cfg.StartupStatus.Redis.Password,
136				DB:       cfg.StartupStatus.Redis.DB,
137			})
138			if err != nil {
139				logging.ComponentWarnEvent("router", "startup_status_redis_fallback", map[string]interface{}{
140					"error":    err.Error(),
141					"fallback": "file",
142				})
143				return startupstatus.NewFileWriter(configPath)
144			}
145			logging.ComponentEvent("router", "startup_status_backend", map[string]interface{}{
146				"backend": "redis",
147				"address": cfg.StartupStatus.Redis.Address,
148			})
149			return rw
150		}
151	
152		logging.ComponentWarnEvent("router", "startup_status_file_backend", map[string]interface{}{
153			"backend": "file",
154			"message": "Startup status using local file backend. Status is not shared across replicas or visible to the dashboard in containerized deployments. Set startup_status.store_backend: redis for production use.",
155		})
156		return startupstatus.NewFileWriter(configPath)
157	}
158	
159	func writeStartupState(writer startupstatus.StatusWriter, state startupstatus.State, warning string) {
160		if err := writer.Write(state); err != nil {
161			logging.ComponentWarnEvent("router", "startup_state_write_failed", map[string]interface{}{
162				"warning": warning,
163				"phase":   state.Phase,
164				"ready":   state.Ready,
165				"error":   err.Error(),
166			})
167		}
168	}
169	
170	func failStartup(writer startupstatus.StatusWriter, format string, args ...interface{}) {
171		message := fmt.Sprintf(format, args...)
172		_ = writer.Write(startupstatus.State{
173			Phase:   "error",
174			Ready:   false,
175			Message: message,
176		})
177		logging.ComponentFatalEvent("router", "startup_failed", map[string]interface{}{
178			"message": message,
179		})
180	}
181	
182	func ensureModelsDownloadedOrFatal(cfg *config.RouterConfig, writer startupstatus.StatusWriter) {
183		if err := ensureModelsDownloaded(cfg, writer); err != nil {
184			failStartup(writer, "Failed to ensure models are downloaded: %v", err)
185		}
186	}
187	
188	func exitIfDownloadOnly(downloadOnly bool) {
189		if !downloadOnly {
190			return
191		}
192	
193		logging.ComponentEvent("router", "download_only_complete", map[string]interface{}{
194			"mode": "download_only",
195		})
196		os.Exit(0)
197	}
