199	func initializeTracing(cfg *config.RouterConfig) func() {
200		if !cfg.Observability.Tracing.Enabled {
201			return func() {}
202		}
203	
204		tracingCfg := tracing.TracingConfig{
205			Enabled:               cfg.Observability.Tracing.Enabled,
206			Provider:              cfg.Observability.Tracing.Provider,
207			ExporterType:          cfg.Observability.Tracing.Exporter.Type,
208			ExporterEndpoint:      cfg.Observability.Tracing.Exporter.Endpoint,
209			ExporterInsecure:      cfg.Observability.Tracing.Exporter.Insecure,
210			SamplingType:          cfg.Observability.Tracing.Sampling.Type,
211			SamplingRate:          cfg.Observability.Tracing.Sampling.Rate,
212			ServiceName:           cfg.Observability.Tracing.Resource.ServiceName,
213			ServiceVersion:        cfg.Observability.Tracing.Resource.ServiceVersion,
214			DeploymentEnvironment: cfg.Observability.Tracing.Resource.DeploymentEnvironment,
215		}
216		if err := tracing.InitTracing(context.Background(), tracingCfg); err != nil {
217			logging.ComponentWarnEvent("router", "tracing_init_failed", map[string]interface{}{
218				"provider":          tracingCfg.Provider,
219				"exporter_type":     tracingCfg.ExporterType,
220				"exporter_endpoint": tracingCfg.ExporterEndpoint,
221				"error":             err.Error(),
222			})
223		}
224		return shutdownTracing
225	}
226	
227	func shutdownTracing() {
228		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
229		defer cancel()
230		if err := tracing.ShutdownTracing(shutdownCtx); err != nil {
231			logging.ComponentErrorEvent("router", "tracing_shutdown_failed", map[string]interface{}{
232				"error": err.Error(),
233			})
234		}
235	}
