253	func registerSignalHandler(shutdownHooks *[]func()) {
254		sigChan := make(chan os.Signal, 1)
255		signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
256	
257		go func() {
258			sig := <-sigChan
259			logging.ComponentEvent("router", "shutdown_signal_received", map[string]interface{}{
260				"signal": sig.String(),
261			})
262			for _, hook := range *shutdownHooks {
263				hook()
264			}
265			shutdownTracing()
266			os.Exit(0)
267		}()
268	}
269	
270	func startMetricsServerIfEnabled(cfg *config.RouterConfig, metricsPort int) {
271		metricsEnabled := true
272		if cfg.Observability.Metrics.Enabled != nil {
273			metricsEnabled = *cfg.Observability.Metrics.Enabled
274		}
275		if metricsPort <= 0 {
276			metricsEnabled = false
277		}
278		if !metricsEnabled {
279			logging.ComponentEvent("router", "metrics_server_disabled", map[string]interface{}{
280				"metrics_port": metricsPort,
281			})
282			return
283		}
284	
285		go func() {
286			http.Handle("/metrics", promhttp.Handler())
287			metricsAddr := fmt.Sprintf(":%d", metricsPort)
288			logging.ComponentEvent("router", "metrics_server_starting", map[string]interface{}{
289				"address": metricsAddr,
290			})
291			if err := http.ListenAndServe(metricsAddr, nil); err != nil {
292				logging.ComponentErrorEvent("router", "metrics_server_failed", map[string]interface{}{
293					"address": metricsAddr,
294					"error":   err.Error(),
295				})
296			}
297		}()
298	}
299	
300	func initializeRuntimeDependencies(
301		cfg *config.RouterConfig,
302		writer startupstatus.StatusWriter,
303		shutdownHooks *[]func(),
304		runtimeRegistry *routerruntime.Registry,
305	) modelruntime.EmbeddingRuntimeState {
306		writeStartupState(writer, startupstatus.State{
307			Phase:   "initializing_models",
308			Ready:   false,
309			Message: "Initializing embedding models and router dependencies...",
310		}, "Failed to write initialization startup status")
311	
312		embeddingState, err := modelruntime.PrepareRouterRuntime(context.Background(), cfg, modelruntime.PrepareRouterRuntimeOptions{
313			Component:                  "router",
314			MaxParallelism:             modelruntime.DefaultParallelism(5),
315			OnEvent:                    logRuntimeLifecycleEvent,
316			InitModalityClassifierFunc: extproc.InitModalityClassifier,
317		})
318		if err != nil {
319			failStartup(writer, "Failed to initialize runtime dependencies: %v", err)
320		}
321		writeStartupState(writer, startupstatus.State{
322			Phase:             "initializing_models",
323			Ready:             false,
324			Message:           "Runtime dependencies initialized. Starting router services...",
325			EmbeddingProvider: startupEmbeddingProviderStatus(embeddingState),
326		}, "Failed to write runtime dependency startup status")
327	
328		initializeVectorStoreIfEnabled(cfg, shutdownHooks, runtimeRegistry)
329		return embeddingState
330	}
331	
332	func startupEmbeddingProviderStatus(state modelruntime.EmbeddingRuntimeState) *startupstatus.EmbeddingProviderStatus {
333		provider := state.EmbeddingProvider
334		if provider == nil {
335			return nil
336		}
337		return &startupstatus.EmbeddingProviderStatus{
338			Mode:           provider.Mode,
339			Backend:        provider.Backend,
340			Model:          provider.Model,
341			Dimension:      provider.Dimension,
342			APIKeyEnv:      provider.APIKeyEnv,
343			APIKeyEnvSet:   cloneBoolPtr(provider.APIKeyEnvSet),
344			Healthy:        cloneBoolPtr(provider.Healthy),
345			LastProbeError: provider.LastProbeError,
346			LastCheckedAt:  provider.LastCheckedAt,
347		}
348	}
349	
350	func cloneBoolPtr(value *bool) *bool {
351		if value == nil {
352			return nil
353		}
354		clone := *value
355		return &clone
356	}
357	
358	func logRuntimeLifecycleEvent(event modelruntime.Event) {
359		if event.Status != modelruntime.TaskFailed && event.Status != modelruntime.TaskSkipped {
360			return
361		}
362		payload := map[string]interface{}{
363			"task":        event.Task,
364			"best_effort": event.BestEffort,
365		}
366		if event.Error != nil {
367			payload["error"] = event.Error.Error()
368		}
369		if event.Status == modelruntime.TaskSkipped {
370			logging.ComponentWarnEvent("router", "runtime_lifecycle_task_skipped", payload)
371			return
372		}
373		if event.BestEffort {
374			logging.ComponentWarnEvent("router", "runtime_lifecycle_task_failed", payload)
375			return
376		}
377		logging.ComponentErrorEvent("router", "runtime_lifecycle_task_failed", payload)
378	}
379	
380	func initializeVectorStoreIfEnabled(
381		cfg *config.RouterConfig,
382		shutdownHooks *[]func(),
383		runtimeRegistry *routerruntime.Registry,
384	) {
385		if cfg.VectorStore == nil || !cfg.VectorStore.Enabled {
386			return
387		}
388	
389		logging.ComponentEvent("router", "vector_store_init_started", map[string]interface{}{
390			"backend": cfg.VectorStore.BackendType,
391		})
392		if err := cfg.VectorStore.Validate(); err != nil {
393			logging.ComponentFatalEvent("router", "vector_store_config_invalid", map[string]interface{}{
394				"backend": cfg.VectorStore.BackendType,
395				"error":   err.Error(),
396			})
397		}
398		vectorStoreRuntime, err := routerruntime.NewVectorStoreRuntime(cfg)
399		if err != nil {
400			logging.ComponentFatalEvent("router", "vector_store_runtime_create_failed", map[string]interface{}{
401				"backend": cfg.VectorStore.BackendType,
402				"error":   err.Error(),
403			})
404		}
405		if runtimeRegistry != nil {
406			runtimeRegistry.SetVectorStoreRuntime(vectorStoreRuntime)
407		}
408		vectorStoreRuntime.LogInitialized("router", cfg)
409		registerVectorStoreShutdownHook(shutdownHooks, vectorStoreRuntime)
410	}
411	
412	func registerVectorStoreShutdownHook(
413		shutdownHooks *[]func(),
414		vectorStoreRuntime *routerruntime.VectorStoreRuntime,
415	) {
416		*shutdownHooks = append(*shutdownHooks, func() {
417			logging.ComponentEvent("router", "vector_store_shutdown_started", map[string]interface{}{})
418			if err := vectorStoreRuntime.Shutdown(); err != nil {
419				logging.ComponentErrorEvent("router", "vector_store_shutdown_failed", map[string]interface{}{
420					"error": err.Error(),
421				})
422			}
423		})
424	}
425	
426	func newExtProcServerOrFatal(
427		opts runtimeOptions,
428		writer startupstatus.StatusWriter,
429		runtimeRegistry *routerruntime.Registry,
430	) *extproc.Server {
