			Ready:      embeddingState.AnyReady,
			SkipReason: "embedding_runtime_not_ready_for_knowledge_bases",
			Load:       router.PreloadKnowledgeBases,
		},
	}, modelruntime.WarmupRouterOptions{
		Component:      "router",
		MaxParallelism: 2,
		OnEvent:        logRuntimeLifecycleEvent,
	})
